// Build a safe, whitelisted SQL query from the dashboard filters
const body = $json.body || {};
const f = (body && typeof body.filters === 'object' && body.filters) ? body.filters : {};

const CRIME_TYPES = ['violent','financial','cyber','trafficking','terrorism','ai_enabled','children','drugs','organized_crime','other'];
const REGIONS = ['UAE','GCC','Middle_East','Europe','Americas','Africa','Asia','Oceania','Global'];
const SOURCE_TYPES = ['academic','governmental','international_org','news'];
const SCOPES = ['local','regional','international'];

const esc = (s) => String(s).replace(/'/g, "''");
const isDate = (s) => /^\d{4}-\d{2}-\d{2}$/.test(String(s || ''));

const conditions = [];

if (Array.isArray(f.crime_types)) {
  const valid = f.crime_types.filter((c) => CRIME_TYPES.includes(c));
  if (valid.length) {
    conditions.push(`crime_type && ARRAY[${valid.map((c) => `'${c}'`).join(', ')}]::crime_type_enum[]`);
  }
}

if (Array.isArray(f.regions)) {
  const valid = f.regions.filter((r) => REGIONS.includes(r));
  if (valid.length) {
    conditions.push(`region && ARRAY[${valid.map((r) => `'${r}'`).join(', ')}]::region_enum[]`);
  }
}

if (SOURCE_TYPES.includes(f.source_type)) conditions.push(`source_type = '${f.source_type}'`);
if (SCOPES.includes(f.scope)) conditions.push(`geographical_scope = '${f.scope}'`);
if (isDate(f.date_from)) conditions.push(`publication_date >= '${f.date_from}'`);
if (isDate(f.date_to)) conditions.push(`publication_date <= '${f.date_to}'`);

const relevanceMin = parseInt(f.relevance_min, 10);
if (relevanceMin >= 1 && relevanceMin <= 5) conditions.push(`relevance_score >= ${relevanceMin}`);

if (typeof f.search === 'string' && f.search.trim()) {
  const term = esc(f.search.trim());
  conditions.push(`(title ILIKE '%${term}%' OR COALESCE(title_ar, '') ILIKE '%${term}%' OR COALESCE(abstract, '') ILIKE '%${term}%')`);
}

const whereClause = conditions.length ? 'WHERE ' + conditions.join('\n  AND ') : '';
const limit = Math.min(Math.max(parseInt(f.limit, 10) || 2000, 1), 5000);

const query = `SELECT id, title, title_ar, authors, publication_date, source_type, source_name, url,
       crime_type, geographical_scope, region, language, relevance_score, date_added
FROM criminal_references
${whereClause}
ORDER BY publication_date DESC NULLS LAST, id DESC
LIMIT ${limit};`;

return [{ json: { query, filters: f } }];

// Wrap query rows in the dashboard response envelope
const rows = $input.all().map((i) => i.json).filter((r) => r && r.id !== undefined);
return [{
  json: {
    success: true,
    operation: 'GET_DASHBOARD_DATA',
    count: rows.length,
    generated_at: new Date().toISOString(),
    records: rows,
  },
}];

// Build a safe, whitelisted SQL query from the dashboard filters
const body = $json.body || {};
const f = (body && typeof body.filters === 'object' && body.filters) ? body.filters : {};

const CRIME_TYPES = ['violent','financial','cyber','trafficking','terrorism','ai_enabled','children','drugs','organized_crime','other'];
const REGIONS = ['UAE','GCC','Middle_East','Europe','Americas','Africa','Asia','Oceania','Global'];
const SOURCE_TYPES = ['academic','governmental','international_org','news'];
const SCOPES = ['local','regional','international'];

const esc = (s) => String(s).replace(/'/g, "''");
const isDate = (s) => /^\d{4}-\d{2}-\d{2}$/.test(String(s || ''));

const conditions = [];

if (Array.isArray(f.crime_types)) {
  const valid = f.crime_types.filter((c) => CRIME_TYPES.includes(c));
  if (valid.length) {
    conditions.push(`crime_type && ARRAY[${valid.map((c) => `'${c}'`).join(', ')}]::crime_type_enum[]`);
  }
}

if (Array.isArray(f.regions)) {
  const valid = f.regions.filter((r) => REGIONS.includes(r));
  if (valid.length) {
    conditions.push(`region && ARRAY[${valid.map((r) => `'${r}'`).join(', ')}]::region_enum[]`);
  }
}

if (SOURCE_TYPES.includes(f.source_type)) conditions.push(`source_type = '${f.source_type}'`);
if (SCOPES.includes(f.scope)) conditions.push(`geographical_scope = '${f.scope}'`);
if (isDate(f.date_from)) conditions.push(`publication_date >= '${f.date_from}'`);
if (isDate(f.date_to)) conditions.push(`publication_date <= '${f.date_to}'`);

const relevanceMin = parseInt(f.relevance_min, 10);
if (relevanceMin >= 1 && relevanceMin <= 5) conditions.push(`relevance_score >= ${relevanceMin}`);

if (typeof f.search === 'string' && f.search.trim()) {
  const term = esc(f.search.trim());
  conditions.push(`(title ILIKE '%${term}%' OR COALESCE(title_ar, '') ILIKE '%${term}%' OR COALESCE(abstract, '') ILIKE '%${term}%')`);
}

const whereClause = conditions.length ? 'WHERE ' + conditions.join('\n  AND ') : '';
const limit = Math.min(Math.max(parseInt(f.limit, 10) || 2000, 1), 5000);

const query = `SELECT id, title, title_ar, authors, publication_date, source_type, source_name, url,
       crime_type, geographical_scope, region, language, relevance_score, date_added
FROM criminal_references
${whereClause}
ORDER BY publication_date DESC NULLS LAST, id DESC
LIMIT ${limit};`;

return [{ json: { query, filters: f } }];

// Aggregate the filtered rows and prepare the report log INSERT
const rows = $input.all().map((i) => i.json).filter((r) => r && r.id !== undefined);
const meta = $('Build Report Query').first().json;
const f = meta.filters || {};

const esc = (s) => String(s).replace(/'/g, "''");
const isDate = (s) => /^\d{4}-\d{2}-\d{2}$/.test(String(s || ''));

const toArray = (v) => {
  if (Array.isArray(v)) return v;
  if (typeof v === 'string') return v.replace(/^\{|\}$/g, '').split(',').map((x) => x.trim()).filter(Boolean);
  return [];
};

const byCrime = {};
const byRegion = {};
const bySource = {};
for (const r of rows) {
  for (const c of toArray(r.crime_type)) byCrime[c] = (byCrime[c] || 0) + 1;
  for (const g of toArray(r.region)) byRegion[g] = (byRegion[g] || 0) + 1;
  if (r.source_type) bySource[r.source_type] = (bySource[r.source_type] || 0) + 1;
}

const today = new Date().toISOString().slice(0, 10);
const reportTitle = `Criminal Intelligence Dashboard Report - ${today}`;
const reportTitleAr = `تقرير لوحة الرصد الجنائي التفاعلية - ${today}`;
const fileName = `dashboard_report_${today.replace(/-/g, '')}.html`;
const periodStart = isDate(f.date_from) ? `'${f.date_from}'` : 'NULL';
const periodEnd = isDate(f.date_to) ? `'${f.date_to}'` : 'NULL';

const query = `INSERT INTO reports (report_type, report_title, report_title_ar, report_date, period_start, period_end, file_name, references_count, sections_count)
VALUES ('dashboard', '${esc(reportTitle)}', '${esc(reportTitleAr)}', '${today}', ${periodStart}, ${periodEnd}, '${esc(fileName)}', ${rows.length}, 4)
RETURNING id;`;

return [{
  json: {
    query,
    report_title: reportTitle,
    report_title_ar: reportTitleAr,
    file_name: fileName,
    count: rows.length,
    stats: { by_crime_type: byCrime, by_region: byRegion, by_source_type: bySource },
    filters: f,
    records: rows.slice(0, 500),
  },
}];

// Combine the report log result with the aggregated stats
const logRow = ($input.first() && $input.first().json) || {};
const build = $('Build Report Stats').first().json;
return [{
  json: {
    success: true,
    operation: 'GENERATE_REPORT',
    report_id: logRow.id || null,
    logged_to_database: Boolean(logRow.id),
    report_title: build.report_title,
    report_title_ar: build.report_title_ar,
    file_name: build.file_name,
    count: build.count,
    stats: build.stats,
    filters: build.filters,
    records: build.records,
    generated_at: new Date().toISOString(),
  },
}];

// Reject unsupported operations
const body = $json.body || {};
return [{
  json: {
    success: false,
    error: 'Unknown operation. Supported operations: GET_DASHBOARD_DATA, GENERATE_REPORT',
    received_operation: body.operation || null,
  },
}];
